from itertools import *
import sys
input = sys.stdin.readline

def inp():
	return int(input())

def st():
	return input().rstrip('\n')

def lis():
	return list(map(int, input().split()))

def ma():
	return map(int, input().split())
t = inp()
while t:
	t -= 1
	(n, k) = ma()
	s = st()
	z = set(list(s))
	if len(z) <= k:
		print(''.join(sorted(list(s))))
		continue
	if k == 1:
		print(s)
		continue
	freq = [0] * 26
	for i in s:
		freq[ord(i) - 97] += 1
	ind = {chr(i + 97): [] for i in range(26)}
	for i in range(n):
		ind[s[i]].append(i)
	res = ''
	vis = [0] * n
	flag = 0
	total = 0
	for i in range(k - 1):
		j = -1
		valid = 0
		if total == n:
			break
		while j < n:
			while valid < 26 and freq[valid] == 0:
				valid += 1
			if valid >= 26:
				break
			cur = chr(97 + valid)
			if ind[cur][-1] < j:
				break
			ex = ind[cur][-1]
			while ind[cur] and ind[cur][-1] > j:
				total += 1
				x = ind[cur].pop()
				vis[x] = 1
				res += cur
				freq[valid] -= 1
			j = ex
	left = ''
	for i in range(1 + j):
		if vis[i]:
			continue
		left += s[i]
	right = ''
	for i in range(j + 1, n):
		if vis[i]:
			continue
		right += s[i]
	cur_pos = 0
	rpart = [[] for i in range(26)]
	for i in range(len(right)):
		z = ord(right[i]) - 97
		rpart[z].append(i)
	for i in range(26):
		rpart[i] = rpart[i][::-1]
	prev = -1
	if left == '' and right == '':
		print(res)
		continue
	while 1:
		minchar = 999
		cmpord = ord(left[cur_pos]) - 97
		for i in range(26):
			if len(rpart[i]):
				if i <= cmpord:
					minchar = i
					break
		if minchar == 999:
			res += left
			res += right[prev + 1:]
			break
		elif minchar != cmpord:
			last = rpart[minchar][0]
			ok_char = chr(minchar + 97)
			res += ok_char * len(rpart[minchar])
			for i in range(prev + 1, last + 1):
				if right[i] != ok_char:
					left += right[i]
			for i in range(26):
				while rpart[i] and rpart[i][-1] <= last:
					rpart[i].pop()
			prev = last
		else:
			string1 = res + left + right[prev + 1:]
			ok_char = chr(minchar + 97)
			last = rpart[minchar][0]
			for i in range(prev + 1, last + 1):
				if right[i] != ok_char:
					left += right[i]
			ok_char = chr(minchar + 97) * len(rpart[minchar])
			string2 = res + ok_char + left + right[last + 1:]
			res = min(string1, string2)
			break
	print(res)
